-- MySQL 8.0.16+. Catalog: execute ONE numbered operation, never the whole file.
-- Bind parameters. All dates UTC. No plaintext passwords or raw tokens in SQL.
USE vacancy_aggregator;

-- QA01. Registration: create account and profile atomically.
-- @auth_subject = new UUID/string ID generated by backend, <=191 characters.
-- @normalized_email = consistent backend normalization of the email for ALL auth operations.
-- @password_hash = salted password hash made by backend password hasher, never SHA256(password).
-- On ANY SQL error backend rolls back; duplicate email means registration conflict.
START TRANSACTION;
INSERT INTO users (id,email,normalized_email,password_hash)
VALUES (@auth_subject,@email,@normalized_email,@password_hash);
INSERT INTO user_profiles (auth_subject,display_name,time_zone)
VALUES (@auth_subject,@display_name,@time_zone);
SELECT LAST_INSERT_ID() AS profile_id;
COMMIT;

-- QA02. Lookup for login, server-side only. Backend verifies password against
-- password_hash with its password hasher, returning a generic error on failure.
-- Never return this resultset, especially password_hash, to the client.
SELECT id AS auth_subject, password_hash
FROM users WHERE normalized_email=@normalized_email AND status='active';

-- QA03. Create an opaque session ONLY AFTER backend verified the password.
-- @token_hash_hex = 64 hex chars of SHA256(random token with >=256 bits entropy).
-- @verified_password_hash = hash actually verified in QA02; guards a concurrent password change.
-- @expires_at = UTC expiration chosen by backend. Exactly 1 affected row required.
-- Client receives the raw token from BACKEND memory; DB never sees that raw token.
INSERT INTO auth_sessions (user_subject,token_hash,expires_at)
SELECT u.id,UNHEX(@token_hash_hex),@expires_at
FROM users u WHERE u.id=@auth_subject AND u.status='active'
  AND u.password_hash=@verified_password_hash
  AND @expires_at > UTC_TIMESTAMP(6)
  AND CHAR_LENGTH(@token_hash_hex)=64 AND @token_hash_hex REGEXP '^[0-9a-fA-F]{64}$';

-- QA04. Resolve authenticated user from token digest. No row = unauthenticated.
-- Backend hashes incoming raw token, binds the digest and uses returned profile_id.
SELECT u.id AS auth_subject, p.id AS profile_id, p.display_name, s.id AS session_id
FROM auth_sessions s JOIN users u ON u.id=s.user_subject
JOIN user_profiles p ON p.auth_subject=u.id
WHERE s.token_hash=UNHEX(@token_hash_hex) AND s.revoked_at IS NULL
  AND s.expires_at > UTC_TIMESTAMP(6) AND u.status='active';

-- QA05. Logout current session; @auth_subject comes from authenticated identity.
UPDATE auth_sessions SET revoked_at=UTC_TIMESTAMP(6)
WHERE token_hash=UNHEX(@token_hash_hex) AND user_subject=@auth_subject AND revoked_at IS NULL;

-- QA06. Logout all sessions for current authenticated account.
UPDATE auth_sessions SET revoked_at=UTC_TIMESTAMP(6)
WHERE user_subject=@auth_subject AND revoked_at IS NULL;

-- QA07. Mark successful login after QA03 inserted 1 row.
UPDATE users SET last_login_at=UTC_TIMESTAMP(6)
WHERE id=@auth_subject AND status='active';
